// Packs workers/h3-runpod (+ the assembler handler and workers/painter) into a gzip tarball and
// embeds it as base64 in src/pod/bundle.ts, so a stock RunPod ComfyUI image
// can bootstrap the studio's job server from GET /api/pod/bundle without a
// Docker build. Runs before dev/build.
//
// A tarball's bytes change with the clock and the machine, so the file is
// rewritten only when the files inside differ from the committed bundle's.
// That keeps `git diff` empty after a run that changed nothing, which is what
// CI checks.
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync, cpSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, join, relative } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const target = join(root, "src/pod/bundle.ts");
const stage = mkdtempSync(join(tmpdir(), "pod-bundle-"));
/* Python's caches are the machine's, not the worker's */
const source = (path) => basename(path) !== "__pycache__" && !path.endsWith(".pyc");
mkdirSync(join(stage, "h3-runpod"), { recursive: true });
for (const f of ["handler.py", "server.py", "start.sh", "requirements.txt", "models.txt", "models-regen.txt", "models-remake.txt", "models-h3-image.txt", "download_models.sh", "retired-models.txt", "remove_retired_models.sh", "voice_handler.py", "voice_worker.py", "voice_setup.sh", "requirements-voice.txt", "models-voice.txt"]) {
  cpSync(join(root, "workers/h3-runpod", f), join(stage, "h3-runpod", f));
}
/* the painter (pictures off the GPU) rides along: the pod runs it as the
   fallback, and a CPU box bootstraps from this same bundle (run_painter.sh) */
for (const f of ["paint.py", "painter.py", "install_codex.sh", "run_painter.sh"]) {
  cpSync(join(root, "workers/painter", f), join(stage, "h3-runpod", f));
}
cpSync(join(root, "workers/h3-runpod/workflows"), join(stage, "h3-runpod/workflows"), { recursive: true, filter: source });
cpSync(join(root, "workers/h3-runpod/studio_nodes"), join(stage, "h3-runpod/studio_nodes"), { recursive: true, filter: source });
cpSync(join(root, "workers/assembler/handler.py"), join(stage, "h3-runpod/assembler_handler.py"));

/* every file under dir: its path, whether it is executable, its bytes */
function contents(dir) {
  const files = new Map();
  const walk = (d) => {
    for (const entry of readdirSync(d, { withFileTypes: true })) {
      const path = join(d, entry.name);
      if (entry.isDirectory()) walk(path);
      else files.set(relative(dir, path), `${statSync(path).mode & 0o111 ? "x" : "-"}${readFileSync(path).toString("base64")}`);
    }
  };
  walk(dir);
  return files;
}

/* the files in the bundle that is committed now; null when there is none to read */
function committed() {
  const b64 = existsSync(target) ? readFileSync(target, "utf8").match(/POD_BUNDLE_BASE64 = "([^"]*)"/)?.[1] : null;
  if (!b64) return null;
  const dir = join(stage, "committed");
  mkdirSync(dir);
  writeFileSync(join(stage, "committed.tgz"), Buffer.from(b64, "base64"));
  try {
    execFileSync("tar", ["-xzf", join(stage, "committed.tgz"), "-C", dir], { stdio: "pipe" });
  } catch {
    return null;
  }
  return contents(dir);
}

const now = contents(join(stage, "h3-runpod"));
const before = committed();
const same = before !== null && before.size === now.size && [...now].every(([path, data]) => before.get(`h3-runpod/${path}`) === data);
if (same) {
  console.log(`src/pod/bundle.ts is up to date (${now.size} files)`);
} else {
  const out = join(stage, "bundle.tgz");
  execFileSync("tar", ["-czf", out, "-C", stage, "h3-runpod"]);
  const b64 = readFileSync(out).toString("base64");
  const ts = `/* Generated by scripts/emit-pod-bundle.mjs — do not edit. gzip tarball of workers/h3-runpod. */\nexport const POD_BUNDLE_BASE64 = ${JSON.stringify(b64)};\nexport const POD_BUNDLE_BYTES = ${readFileSync(out).length};\n`;
  writeFileSync(target, ts);
  console.log(`wrote src/pod/bundle.ts (${Math.round((b64.length * 0.75) / 1024)} KB)`);
}
rmSync(stage, { recursive: true, force: true });
